export const getLiveConfig = <ThrowOnError extends boolean = false>(options?: Options<GetLiveConfigData, ThrowOnError>): RequestResult<GetLiveConfigResponses, GetLiveConfigErrors, ThrowOnError> => (options?.client ?? client).get<GetLiveConfigResponses, GetLiveConfigErrors, ThrowOnError>({ url: '/v1/live/config', ...options });

/**
 * Open the live stream
 *
 * Opens the one server-sent events stream an app holds, naming every
 * channel its screens listen to, comma-separated, from the closed
 * vocabulary (see Live streams on the portal). A name no channel produces
 * is `400` (`channel_unknown`) with `errors` by position. Private channels
 * are authorised when the stream opens, against the caller's own facts,
 * never cached: an open naming a channel the caller may not hear is
 * refused as a whole (`401`, `403` or `404`, `errors` pointing at the
 * refused channel's position), so the client drops it and opens again.
 * Public channels (`broadcast`, `store-{location_id}-menu`) need no
 * credential.
 *
 * | Event            | Data                 | When                                                        |
 * | ---------------- | -------------------- | ----------------------------------------------------------- |
 * | `snapshot`       | `AgentsSnapshot`     | On open, per agent channel                                  |
 * | `resync`         | `Resync`             | On open, per other channel; after a fan-out outage          |
 * | `signal`         | `Signal`             | Something changed; refetch it unless you hold the version   |
 * | `agent.position` | `AgentPositionFrame` | An agent moved                                              |
 * | `agent.status`   | `AgentStatusFrame`   | An agent went online or offline                             |
 * | `heartbeat`      | empty                | Every 15 seconds                                            |
 * | `close`          | `Close`              | The platform ends the stream: `token_expired`, `revoked`, `replaced` |
 *
 * Frames carry no `id` and missed frames are not replayed: after a
 * reconnect the stream starts again with a `snapshot` or `resync` per
 * channel. The stream lives no longer than the access token; a revoked
 * session or a removed membership closes it within a minute; a connection
 * with the same `client_id`, or the fifth connection of a session, replaces
 * the oldest. Treat 45 seconds without a frame as a lost connection and
 * reconnect with backoff.
 *
 */
export const openLiveStream = <ThrowOnError extends boolean = false>(options: Options<OpenLiveStreamData, ThrowOnError, OpenLiveStreamResponse>): Promise<ServerSentEventsResult<OpenLiveStreamResponses>> => (options.client ?? client).sse.get<OpenLiveStreamResponses, OpenLiveStreamErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/v1/live/stream',
    ...options
});

